1	import { z } from 'zod';
2	
3	/**
4	 * Coerces env var strings to boolean.
5	 * Treats 'false', '0', and '' as false; everything else as true.
6	 */
7	export const envBoolean = z.preprocess((val) => {
8	  if (typeof val === 'boolean') return val;
9	  if (typeof val === 'string')
10	    return !['false', '0', ''].includes(val.toLowerCase());
11	  return Boolean(val);
12	}, z.boolean());
13	
14	/** Transforms a comma-separated env var string into a trimmed string array. */
15	export const csvString = z.preprocess((val) => {
16	  if (typeof val !== 'string' || val === '') return [];
17	  return val
18	    .split(',')
19	    .map((s) => s.trim())
20	    .filter(Boolean);
21	}, z.array(z.string()));
22	
23	/** Core config present in every telaio app. */
24	export const coreConfigSchema = z.object({
25	  APP_NAME: z.string().default('App'),
26	  NODE_ENV: z
27	    .enum(['development', 'production', 'test'])
28	    .default('development'),
29	  BASE_DIR: z.string().default(process.cwd()),
30	});
31	
32	/** Server-related config for the Fastify HTTP server. */
33	export const serverConfigSchema = z.object({
34	  API_URL: z.url().default('http://localhost:4001'),
35	  API_LISTEN_PORT: z.coerce.number().default(4001),
36	  API_LISTEN_ADDRESS: z.string().default('0.0.0.0'),
37	  CORS_ORIGINS: csvString.default([]),
38	  WHITELIST_PROXIES: csvString.default([]),
39	  ENABLE_API_DOCS: envBoolean.default(false),
40	});
41	
42	/** Database config for PostgreSQL via Kysely. */
43	export const databaseConfigSchema = z.object({
44	  DATABASE_URL: z.url().default('postgresql://localhost/app'),
45	  DATABASE_SSL: envBoolean.optional(),
46	  DATABASE_CAMEL_CASE: envBoolean.default(true),
47	  DATABASE_MIGRATION_SCHEMA: z
48	    .string()
49	    .min(1)
50	    .regex(/^[a-zA-Z_][a-zA-Z0-9_]*$/)
51	    .optional(),
52	  DATABASE_MIGRATION_TABLE: z
53	    .string()
54	    .min(1)
55	    .regex(/^[a-zA-Z_][a-zA-Z0-9_]*$/)
56	    .optional(),
57	  DATABASE_MIGRATION_LOCK_TABLE: z
58	    .string()
59	    .min(1)
60	    .regex(/^[a-zA-Z_][a-zA-Z0-9_]*$/)
61	    .optional(),
62	  DATABASE_POOL_MAX: z.coerce.number().int().positive().optional(),
63	});
64	
65	/** Redis cache config. */
66	export const cacheConfigSchema = z.object({
67	  REDIS_ENABLED: envBoolean.default(true),
68	  REDIS_URL: z.url().optional(),
69	});
70	
71	/** Queue config for pg-boss. */
72	export const queueConfigSchema = z.object({
73	  QUEUE_SCHEMA: z.string().default('pgboss'),
74	});
75	
76	/** S3 config for AWS S3 client. */
77	export const s3ConfigSchema = z.object({
78	  AWS_S3_REGION: z
79	    .string()
80	    .default(
81	      process.env.AWS_REGION ?? process.env.AWS_DEFAULT_REGION ?? 'us-east-1',
82	    ),
83	  AWS_S3_BUCKET_NAME: z.string().default('assets'),
84	  AWS_S3_ENDPOINT: z.string().optional(),
85	  AWS_S3_ACCESS_KEY_ID: z.string().optional(),
86	  AWS_S3_SECRET_ACCESS_KEY: z.string().optional(),
87	});
88	
89	/** Email config for AWS SES. */
90	export const emailConfigSchema = z.object({
91	  AWS_SES_REGION: z.string().default('us-east-1'),
92	  EMAIL_FROM: z.string().default('noreply@example.com'),
93	});
94	
95	export type CoreConfig = z.infer<typeof coreConfigSchema>;
96	export type ServerConfig = z.infer<typeof serverConfigSchema>;
97	export type DatabaseConfig = z.infer<typeof databaseConfigSchema>;
98	export type CacheConfig = z.infer<typeof cacheConfigSchema>;
99	export type QueueConfig = z.infer<typeof queueConfigSchema>;
100	export type S3Config = z.infer<typeof s3ConfigSchema>;
101	export type EmailConfig = z.infer<typeof emailConfigSchema>;
