4	/**
5	 * Options for creating a pg-boss instance.
6	 * Accepts either a connection string or a config object with DATABASE_URL.
7	 */
8	export interface QueueClientOptions {
9	  /** PostgreSQL connection string. */
10	  connectionString?: string;
11	  /** Schema name for pg-boss tables. Defaults to 'pgboss'. */
12	  schema?: string;
13	  /**
14	   * Force SSL on/off. When omitted, SSL is auto-enabled for AWS RDS endpoints.
15	   * Forwarded to the underlying pg.Pool used by pg-boss.
16	   */
17	  ssl?: boolean;
18	}
19	
20	interface ResolvedQueueOptions {
21	  connectionString: string;
22	  schema: string;
23	  ssl?: { rejectUnauthorized: boolean };
24	}
25	
26	/**
27	 * Resolves queue options from either direct options or a config-style object.
28	 * Exported for testing.
29	 */
30	export function _resolveQueueOptions(
31	  options: QueueClientOptions | Record<string, unknown>,
32	): ResolvedQueueOptions {
33	  return resolveOptions(options);
34	}
35	
36	function resolveOptions(
37	  options: QueueClientOptions | Record<string, unknown>,
38	): ResolvedQueueOptions {
39	  const queueOpts = options as QueueClientOptions;
40	  const cfg = options as Record<string, unknown>;
41	
42	  const connectionString =
43	    queueOpts.connectionString ?? (cfg.DATABASE_URL as string | undefined);
44	
45	  if (!connectionString || typeof connectionString !== 'string') {
46	    throw new Error(
47	      'telaio: queue requires a connectionString or DATABASE_URL in config.',
48	    );
49	  }
50	
51	  const explicitSsl =
52	    queueOpts.ssl ?? (cfg.DATABASE_SSL as boolean | undefined);
53	  const sslEnabled = shouldEnableSsl(connectionString, explicitSsl);
54	
55	  return {
56	    connectionString,
57	    schema: queueOpts.schema ?? 'pgboss',
58	    ...(sslEnabled ? { ssl: { rejectUnauthorized: false } } : {}),
59	  };
60	}
61	
62	// biome-ignore lint/suspicious/noExplicitAny: pg-boss instance from dynamic import
63	let bossInstance: any | null = null;
64	// biome-ignore lint/suspicious/noExplicitAny: promise wrapping pg-boss instance
65	let startPromise: Promise<any> | null = null;
66	
67	/**
68	 * Returns the shared pg-boss instance, creating and starting it on first call.
69	 * Subsequent calls return the same started instance. Safe to call concurrently —
70	 * the start promise is cached to prevent duplicate initialization.
71	 */
72	export async function getBoss(
73	  options: QueueClientOptions | Record<string, unknown>,
74	  logger?: Logger,
75	): Promise<import('pg-boss').PgBoss> {
76	  if (bossInstance) return bossInstance;
77	
78	  if (!startPromise) {
79	    startPromise = (async () => {
80	      let pgBossModule: Record<string, unknown>;
81	      try {
82	        pgBossModule = await import('pg-boss');
83	      } catch {
84	        throw new Error(
85	          "telaio: queue requires 'pg-boss' to be installed. Run: pnpm add pg-boss",
86	        );
87	      }
88	
89	      const resolved = resolveOptions(options);
90	      const queueLogger = logger?.child({ module: 'queue' });
91	
92	      // pg-boss exports { PgBoss } as named export
93	      const PgBossClass =
94	        (pgBossModule.PgBoss as new (
95	          opts: Record<string, unknown>,
96	        ) => Record<string, unknown>) ??
97	        (pgBossModule.default as new (
98	          opts: Record<string, unknown>,
99	        ) => Record<string, unknown>);
100	
101	      if (!PgBossClass) {
102	        throw new Error(
103	          'telaio: could not find PgBoss constructor in pg-boss module.',
104	        );
105	      }
106	
107	      const instance = new PgBossClass(
108	        resolved as unknown as Record<string, unknown>,
109	      );
110	
111	      if (typeof instance.on === 'function') {
112	        instance.on('error', (err: Error) =>
113	          queueLogger?.error({ err }, 'pg-boss error'),
114	        );
115	      }
116	
117	      if (typeof instance.start === 'function') {
118	        await (instance.start as () => Promise<unknown>)();
119	      }
120	
121	      queueLogger?.info('pg-boss started');
122	      bossInstance = instance;
123	      return instance;
124	    })();
125	  }
126	
127	  return startPromise;
128	}
