130	/**
131	 * Gracefully stops the pg-boss instance, allowing in-flight jobs up to 30 seconds
132	 * to complete before forcing shutdown.
133	 */
134	export async function stopBoss(logger?: Logger): Promise<void> {
135	  if (!bossInstance) return;
136	  const queueLogger = logger?.child({ module: 'queue' });
137	  await bossInstance.stop({ graceful: true, timeout: 30_000 });
138	  queueLogger?.info('pg-boss stopped');
139	  bossInstance = null;
140	  startPromise = null;
141	}
142	
143	/** Resets the internal singleton state. For testing only. */
144	export function _resetBoss(): void {
145	  bossInstance = null;
146	  startPromise = null;
147	}

